insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  25,
  $wyb$A prospecting tool that researches a target prospect's public presence and company news, finds a verified email via Hunter.io -- skipping anything below a confidence threshold, enforced in code -- asks the AI to map likely pain points to your value propositions, writes a personalized cold email checked against a list of generic filler phrases known to hurt reply rates, generates 5 ranked subject line options with a hard character limit, and drafts a complete 3-touch follow-up sequence.$wyb$,
  $wyl$[
  "Enforce an email-confidence threshold in code rather than trusting every result an API returns",
  "Ground a personalization prompt in real research, with a guard against inventing a recent event that wasn't found",
  "Check generated copy against a list of phrases known to hurt reply rates - not just ask the AI to avoid them",
  "Enforce a subject-line character limit in code, never trusted to the AI's own count",
  "Validate a follow-up sequence has every required touch before it's considered complete",
  "Build sequencing tool exports as an adaptable template rather than a one-tool-only integration"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "125 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A Tavily API key (free tier at tavily.com) and a Hunter.io API key (free tier)",
    "A VALUE_PROPS file describing your product's key selling points"
  ],
  "outcomes": [
    "Research a prospect's public presence and company news, and find a verified email with a confidence threshold enforced in code",
    "Extract structured intelligence from research without inventing a recent event that wasn't found",
    "Map real challenges to your value propositions with a tested fallback for anything unmatched",
    "Write personalized cold emails checked against a list of phrases known to hurt reply rates",
    "Generate subject lines with a hard character limit enforced in code, never trusted to the AI",
    "Build and validate a complete 3-touch follow-up sequence before it's considered ready to schedule"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Research the prospect and find a verified email",
      "time": "30 min",
      "description": "Gather public context on the prospect and their company, then find a verified email address - skipping anything too risky to send to.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with this content, then replace the placeholders with your real keys:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# Tavily search - free tier gives you 1,000 searches/month\nTAVILY_API_KEY=tvly-paste_your_own_key_here\n\n# Hunter.io - free tier available\nHUNTER_API_KEY=paste_your_own_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `enrich.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Sales Email Personalization Agent (part 1).\n\nSearches for public context on a prospect and their company using\nTavily - not scraping LinkedIn directly, which avoids its anti-scraping\nmeasures entirely. The result-parsing helper is pure and tested below\nagainst fake Tavily responses; only the live search needs a real key.\n\"\"\"\n\nimport os\n\nfrom dotenv import load_dotenv\nfrom tavily import TavilyClient\n\nload_dotenv()\n\nRESULTS_PER_SEARCH = 3\n\n\ndef _parse_results(raw_results, max_results=RESULTS_PER_SEARCH):\n    \"\"\"\n    Turns Tavily's raw result list into a list of plain content\n    snippets, capped at max_results.\n\n        _parse_results([{\"title\": \"...\", \"content\": \"...\"}, ...])\n        -> [\"...\", \"...\"]\n\n    Pure function - tested below without hitting Tavily.\n    \"\"\"\n    return [r.get(\"content\", \"\").strip() for r in raw_results[:max_results] if r.get(\"content\")]\n\n\ndef enrich_prospect(name, company):\n    \"\"\"\n    Searches for the prospect's public presence and recent company\n    news, and returns {\"profile\": [...], \"news\": [...]}.\n    \"\"\"\n    api_key = os.environ.get(\"TAVILY_API_KEY\")\n    if not api_key:\n        raise RuntimeError(\"No TAVILY_API_KEY found. Get a free key at tavily.com and add it to .env.\")\n\n    client = TavilyClient(api_key=api_key)\n\n    profile_response = client.search(query=f\"{name} {company} LinkedIn\", max_results=RESULTS_PER_SEARCH)\n    news_response = client.search(query=f\"{company} news 2026\", max_results=RESULTS_PER_SEARCH)\n\n    return {\n        \"profile\": _parse_results(profile_response.get(\"results\", [])),\n        \"news\": _parse_results(news_response.get(\"results\", [])),\n    }\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no network\n    # call, no API key needed:  python enrich.py\n    fake_results = [\n        {\"title\": \"A\", \"content\": \"Jordan Lee is VP of Engineering at Acme Robotics.\"},\n        {\"title\": \"B\", \"content\": \"\"},\n        {\"title\": \"C\", \"content\": \"Acme Robotics raised a Series B in 2026.\"},\n        {\"title\": \"D\", \"content\": \"This should be cut off by the max_results cap.\"},\n    ]\n    parsed = _parse_results(fake_results, max_results=3)\n    assert len(parsed) == 2  # only the first 3 items are considered; the empty-content one is skipped\n    print(\"Parsed\", len(parsed), \"results, empty content correctly skipped:\")\n    for p in parsed:\n        print(\" -\", p)\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python enrich.py` (no network call, no API key needed - this only tests parsing against fake results). You should see 2 of 4 fake results kept (the empty-content one correctly skipped), ending with `All checks passed.`"
        },
        {
          "instruction": "Create `hunter.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Sales Email Personalization Agent (part 2) - finds and\nverifies an email address with Hunter.io.\n\"\"\"\n\nimport requests\n\n# Hunter.io itself recommends treating anything below this confidence\n# score as too risky to send to - sending to an unverified address hurts\n# sender reputation and deliverability for every FUTURE email you send,\n# not just this one.\nMIN_CONFIDENCE = 50\n\nHUNTER_URL = \"https://api.hunter.io/v2/email-finder\"\n\n\ndef is_confident_enough(confidence, min_confidence=MIN_CONFIDENCE):\n    \"\"\"Pure function - tested below without a real Hunter.io account.\"\"\"\n    return confidence is not None and confidence >= min_confidence\n\n\ndef find_email(first_name, last_name, domain, api_key):\n    \"\"\"\n    Calls Hunter.io's Email Finder API and returns\n    {\"email\": ..., \"confidence\": ..., \"usable\": bool}.\n\n    \"usable\" is False (not just a low number left for you to interpret)\n    when confidence is below MIN_CONFIDENCE or no email was found at\n    all - main.py skips sending to any prospect where usable is False.\n    \"\"\"\n    response = requests.get(\n        HUNTER_URL,\n        params={\"domain\": domain, \"first_name\": first_name, \"last_name\": last_name, \"api_key\": api_key},\n        timeout=15,\n    )\n    response.raise_for_status()\n    data = response.json().get(\"data\", {})\n\n    email = data.get(\"email\")\n    confidence = data.get(\"score\")\n\n    return {\n        \"email\": email,\n        \"confidence\": confidence,\n        \"usable\": bool(email) and is_confident_enough(confidence),\n    }\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the confidence guard works - no\n    # Hunter.io account or network call needed:  python hunter.py\n    assert is_confident_enough(75) is True\n    assert is_confident_enough(50) is True  # boundary is inclusive\n    assert is_confident_enough(49) is False\n    assert is_confident_enough(None) is False\n    print(\"Confidence threshold correctly applied: 75/50 usable, 49/None not usable.\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python hunter.py`. You should see confidence 75 and 50 correctly usable, and 49 and None correctly not usable, ending with `All checks passed.`"
        },
        {
          "instruction": "Now run both live functions on a real name + company + domain:",
          "prompt": "python -c \"from enrich import enrich_prospect; from hunter import find_email; import os; from dotenv import load_dotenv; load_dotenv(); print(enrich_prospect('a real name', 'a real company')); print(find_email('First', 'Last', 'companydomain.com', os.environ['HUNTER_API_KEY']))\"",
          "verify": "You should get back profile and news results, plus an email with a confidence score. If usable is False, that's the guard working as intended - Hunter's free tier doesn't cover every domain."
        }
      ],
      "goFurther": "🛠️ Cache enrichment results per company for 7 days (e.g. a small JSON file keyed by company name) so you don't re-search the same company for every contact there."
    },
    {
      "number": 2,
      "title": "Extract intelligence and map to value props",
      "time": "30 min",
      "description": "Have the AI turn raw research into a structured profile, then match their challenges to what you sell.",
      "steps": [
        {
          "instruction": "Create `intelligence.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Sales Email Personalization Agent (part 1) - turns raw\nresearch into a structured profile: role, responsibilities, challenges,\nand one recent event to personalize an opener with.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\n\ndef build_prompt(name, company, enriched):\n    profile_text = \"\\n\".join(enriched.get(\"profile\", [])) or \"(no profile information found)\"\n    news_text = \"\\n\".join(enriched.get(\"news\", [])) or \"(no recent news found)\"\n\n    return f\"\"\"Prospect: {name} at {company}\n\nPublic profile search results:\n{profile_text}\n\nRecent company news:\n{news_text}\n\nExtract: likely role/title, key responsibilities, 2-3 likely current\nbusiness challenges, and one recent notable event about the company\nuseful for a personalized opening line.\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"role\": \"...\", \"responsibilities\": \"...\", \"challenges\": [\"...\", \"...\"], \"recent_event\": \"...\"}}\n\nDo not invent specifics that aren't implied by the research above - if\nnothing notable was found, say so plainly in recent_event rather than\nfabricating an event.\"\"\"\n\n\ndef parse_intelligence_reply(reply):\n    \"\"\"Defensive JSON parsing, same pattern used throughout this course. Returns None on real garbage.\"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        return json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n\n\ndef extract_intelligence(name, company, enriched):\n    \"\"\"The main function. Give it the prospect's name, company, and enriched research, get back the structured profile.\"\"\"\n    prompt = build_prompt(name, company, enriched)\n    reply = ask_ai(prompt, max_tokens=500, project=\"sales-email-personalization-agent\")\n\n    intel = parse_intelligence_reply(reply)\n    if intel is None:\n        raise ValueError(\"The AI's reply wasn't valid JSON.\\nRun it again - this usually fixes itself.\")\n\n    return intel\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check prompt-building and parsing work\n    # - no AI call, no credits spent:  python intelligence.py\n    enriched = {\"profile\": [\"Jordan Lee is VP of Engineering at Acme Robotics.\"], \"news\": [\"Acme Robotics raised a Series B in 2026.\"]}\n\n    print(\"Checking build_prompt() includes the real research...\")\n    prompt = build_prompt(\"Jordan Lee\", \"Acme Robotics\", enriched)\n    assert \"VP of Engineering\" in prompt\n    assert \"Series B\" in prompt\n    print(\"  OK\")\n\n    print(\"\\nChecking build_prompt() handles empty research without crashing...\")\n    empty_prompt = build_prompt(\"Jordan Lee\", \"Acme Robotics\", {\"profile\": [], \"news\": []})\n    assert \"no profile information found\" in empty_prompt\n    assert \"no recent news found\" in empty_prompt\n    print(\"  OK\")\n\n    print(\"\\nChecking parse_intelligence_reply() strips a ```json code fence...\")\n    fenced = '```json\\n{\"role\": \"VP Engineering\"}\\n```'\n    assert parse_intelligence_reply(fenced) == {\"role\": \"VP Engineering\"}\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python intelligence.py` (no AI call, no credits spent). You should see real research correctly included in the prompt, empty research handled without crashing, and a ```json-fenced reply correctly parsed, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `mapping.py` with this code, then edit VALUE_PROPS to describe your own product's actual selling points:",
          "prompt": "\"\"\"\nStep 2 of the Sales Email Personalization Agent (part 2) - maps a\nprospect's challenges to your product's value propositions. Shared\nacross the whole sales team so messaging stays consistent.\n\"\"\"\n\nVALUE_PROPS = {\n    \"manual reporting\": \"Our platform auto-generates reports, saving 5+ hours/week\",\n    \"scaling support\": \"Our AI agents handle tier-1 tickets so your team focuses on complex cases\",\n    \"slow onboarding\": \"Our guided setup gets new customers live in under a day\",\n}\n\n\ndef map_value_props(challenges):\n    \"\"\"\n    Checks each challenge string for any VALUE_PROPS keyword\n    (case-insensitive) and returns matching value props, falling back\n    to the first value prop if nothing matches.\n\n        map_value_props([\"Struggling with manual reporting workflows\"])\n        -> [\"Our platform auto-generates reports, saving 5+ hours/week\"]\n\n    Pure function - tested below without any AI call.\n    \"\"\"\n    matched = []\n    for challenge in challenges:\n        challenge_lower = challenge.lower()\n        for keyword, value_prop in VALUE_PROPS.items():\n            if keyword in challenge_lower and value_prop not in matched:\n                matched.append(value_prop)\n\n    if not matched:\n        matched.append(next(iter(VALUE_PROPS.values())))\n\n    return matched\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the mapping works - no AI call,\n    # no credits spent:  python mapping.py\n    print(\"Checking a challenge that matches a keyword...\")\n    result = map_value_props([\"Struggling with manual reporting workflows\"])\n    assert result == [\"Our platform auto-generates reports, saving 5+ hours/week\"]\n    print(\"  OK -\", result)\n\n    print(\"\\nChecking case-insensitivity...\")\n    result = map_value_props([\"MANUAL REPORTING takes forever\"])\n    assert len(result) == 1\n    print(\"  OK - matched despite different casing\")\n\n    print(\"\\nChecking multiple challenges matching different props...\")\n    result = map_value_props([\"manual reporting is slow\", \"scaling support is hard\"])\n    assert len(result) == 2\n    print(\"  OK -\", result)\n\n    print(\"\\nChecking a challenge matching NOTHING falls back to the first value prop...\")\n    result = map_value_props([\"their coffee machine is broken\"])\n    assert result == [next(iter(VALUE_PROPS.values()))]\n    print(\"  OK - fell back correctly instead of returning an empty list\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python mapping.py`. You should see a matching challenge correctly mapped, case-insensitivity confirmed, multiple challenges correctly mapping to multiple props, and a completely unrelated challenge correctly falling back to the first value prop instead of an empty list - ending with `All checks passed.`"
        },
        {
          "instruction": "Now run extract_intelligence() for real on your enriched data from Build 1:",
          "prompt": "python -c \"from enrich import enrich_prospect; from intelligence import extract_intelligence; from mapping import map_value_props; enriched = enrich_prospect('a real name', 'a real company'); intel = extract_intelligence('a real name', 'a real company', enriched); print(intel); print(map_value_props(intel['challenges']))\"",
          "verify": "Confirm it returns role, responsibilities, 2-3 challenges, and a recent_event - then confirm map_value_props() returns at least one matching value prop for those challenges."
        }
      ],
      "goFurther": "🛠️🛠️ Add a second VALUE_PROPS tier for different personas (e.g. 'for CFOs' vs 'for VP Engineering') and pick the tier based on the extracted role."
    },
    {
      "number": 3,
      "title": "Write the cold email and generate subject lines",
      "time": "35 min",
      "description": "Draft a short, personalized email with a clear CTA, then generate and rank subject line options - both checked in code against the exact rules the prompt already asked for, not just hoped for.",
      "steps": [
        {
          "instruction": "Create `write_email.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Sales Email Personalization Agent (part 1) - writes the\npersonalized cold email. This project's safety guard checks the\ngenerated email against a list of banned generic filler phrases, since\n\"I hope this finds you well\" measurably hurts reply rates and a prompt\ninstruction alone doesn't always stop a model from reaching for it.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\nMAX_WORDS = 100\n\n# Phrases that measurably hurt cold email reply rates - banned in the\n# prompt AND checked again here, the same \"don't just ask, verify\"\n# pattern used throughout this course.\nBANNED_PHRASES = [\n    \"i hope this finds you well\", \"i hope this email finds you well\",\n    \"i hope you're doing well\", \"i hope all is well\",\n    \"just checking in\", \"circle back\", \"touch base\",\n]\n\n\ndef build_prompt(name, company, intel, value_prop):\n    challenge = intel[\"challenges\"][0] if intel.get(\"challenges\") else \"growing efficiently\"\n\n    return f\"\"\"Write a cold email to {name} at {company}.\n\nOpen by referencing this specific recent event: {intel.get('recent_event', '(none available - open on their likely challenge instead)')}\nMention this likely challenge: {challenge}\nConnect it to this value proposition: {value_prop}\n\nRules:\n- Under 100 words\n- End with exactly one low-friction call to action (e.g. \"Worth a quick chat?\")\n- NEVER use generic openers like \"I hope this finds you well\", \"I hope you're doing well\", \"just checking in\", \"circle back\", or \"touch base\"\n- No subject line - just the email body\"\"\"\n\n\ndef contains_banned_phrase(email_text):\n    \"\"\"\n    Returns True if the email uses one of the exact phrases known to\n    hurt reply rates.\n\n        contains_banned_phrase(\"I hope this finds you well, Jordan...\") -> True\n    \"\"\"\n    lowered = email_text.lower()\n    return any(phrase in lowered for phrase in BANNED_PHRASES)\n\n\ndef write_cold_email(name, company, intel, value_prop):\n    \"\"\"\n    The main function. Give it the prospect's details, get back the\n    email body - or raises ValueError if it used a banned phrase, so\n    main.py never silently sends a generic-sounding email.\n    \"\"\"\n    prompt = build_prompt(name, company, intel, value_prop)\n    email_text = ask_ai(prompt, max_tokens=300, project=\"sales-email-personalization-agent\")\n\n    if contains_banned_phrase(email_text):\n        raise ValueError(\n            \"The AI used a banned generic filler phrase despite being told not to. \"\n            \"Refusing to use this draft automatically - review it manually:\\n\\n\" + email_text\n        )\n\n    word_count = len(email_text.split())\n    if word_count > MAX_WORDS:\n        print(f\"  Note: email came back at {word_count} words (target under {MAX_WORDS}) - worth a manual trim.\")\n\n    return email_text\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check prompt-building and the banned-\n    # phrase guard work - no AI call, no credits spent:  python write_email.py\n    intel = {\"challenges\": [\"manual reporting takes too long\"], \"recent_event\": \"Acme Robotics raised a Series B in 2026\"}\n\n    print(\"Checking build_prompt() includes the real details...\")\n    prompt = build_prompt(\"Jordan Lee\", \"Acme Robotics\", intel, \"Our platform auto-generates reports\")\n    assert \"Series B\" in prompt\n    assert \"manual reporting\" in prompt\n    assert \"I hope this finds you well\" in prompt  # correctly present as a BANNED example, not used\n    print(\"  OK\")\n\n    print(\"\\nChecking contains_banned_phrase()...\")\n    assert contains_banned_phrase(\"I hope this finds you well, Jordan!\")\n    assert contains_banned_phrase(\"Just wanted to touch base about your reporting workflow.\")\n    assert not contains_banned_phrase(\"Saw Acme Robotics just raised a Series B - congrats.\")\n    print(\"  OK - banned openers correctly flagged, a genuine personalized opener correctly left alone\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python write_email.py` (no AI call, no credits spent). You should see the real details correctly included in the prompt, a banned opener correctly flagged, a 'touch base' phrase correctly flagged, and a genuine personalized opener correctly left alone - ending with `All checks passed.`"
        },
        {
          "instruction": "Create `subjects.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Sales Email Personalization Agent (part 2) - generates\nand ranks subject line options, with a hard character limit enforced in\ncode rather than trusted to the AI's own count.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\nMAX_SUBJECT_LENGTH = 50\n\n\ndef build_prompt(email_body):\n    return f\"\"\"Here is a cold email body:\n{email_body}\n\nGenerate 5 subject line options, each under {MAX_SUBJECT_LENGTH}\ncharacters. Rank them 1-5 by predicted open rate, with a one-phrase\nreason for each ranking.\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"subjects\": [{{\"text\": \"...\", \"rank\": 1, \"reason\": \"...\"}}]}}\"\"\"\n\n\ndef parse_subjects_reply(reply):\n    \"\"\"Defensive JSON parsing, same pattern used throughout this course. Returns None on real garbage.\"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        data = json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n    return data.get(\"subjects\", [])\n\n\ndef enforce_length_limit(subjects):\n    \"\"\"\n    Truncates any subject line over MAX_SUBJECT_LENGTH in CODE, never\n    trusting the AI's own character count - the same pattern used for\n    SEO meta titles elsewhere in this course.\n\n        enforce_length_limit([{\"text\": \"x\" * 80, \"rank\": 1, \"reason\": \"...\"}])\n    \"\"\"\n    for subject in subjects:\n        text = subject.get(\"text\", \"\")\n        if len(text) > MAX_SUBJECT_LENGTH:\n            subject[\"text\"] = text[:MAX_SUBJECT_LENGTH].rsplit(\" \", 1)[0]\n    return subjects\n\n\ndef generate_subject_lines(email_body):\n    \"\"\"The main function. Give it the email body, get back up to 5 validated subject line options.\"\"\"\n    prompt = build_prompt(email_body)\n    reply = ask_ai(prompt, max_tokens=300, project=\"sales-email-personalization-agent\")\n\n    subjects = parse_subjects_reply(reply)\n    if subjects is None:\n        raise ValueError(\"The AI's reply wasn't valid JSON.\\nRun it again - this usually fixes itself.\")\n\n    return enforce_length_limit(subjects)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and the length guard\n    # work - no AI call, no credits spent:  python subjects.py\n    print(\"Checking a subject line within the limit passes through unchanged...\")\n    fine_subjects = [{\"text\": \"Quick question about Acme's reporting\", \"rank\": 1, \"reason\": \"specific\"}]\n    result = enforce_length_limit(fine_subjects)\n    assert result[0][\"text\"] == \"Quick question about Acme's reporting\"\n    print(\"  OK\")\n\n    print(\"\\nChecking an over-limit subject gets truncated without cutting mid-word...\")\n    long_subjects = [{\"text\": \"This subject line is definitely way too long for a real cold email subject\", \"rank\": 1, \"reason\": \"x\"}]\n    result = enforce_length_limit(long_subjects)\n    assert len(result[0][\"text\"]) <= MAX_SUBJECT_LENGTH\n    assert not result[0][\"text\"].endswith(\" \")\n    print(f\"  OK - truncated to {len(result[0]['text'])} chars: {result[0]['text']!r}\")\n\n    print(\"\\nChecking parse_subjects_reply() strips a ```json code fence...\")\n    fenced = '```json\\n{\"subjects\": [{\"text\": \"Hi\", \"rank\": 1, \"reason\": \"x\"}]}\\n```'\n    assert len(parse_subjects_reply(fenced)) == 1\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python subjects.py`. You should see an in-limit subject pass through unchanged, an over-limit one truncated without cutting mid-word, and a ```json-fenced reply correctly parsed - ending with `All checks passed.`"
        },
        {
          "instruction": "Now run both for real on your intel from Build 2:",
          "prompt": "python -c \"from write_email import write_cold_email; from subjects import generate_subject_lines; email = write_cold_email('a real name', 'a real company', intel, value_prop); print(email); print(generate_subject_lines(email))\"",
          "verify": "Confirm the email is under 100 words, references the recent_event, ends with a CTA, and has no banned filler phrases. Confirm you get 5 ranked subject line options, each under 50 characters."
        }
      ],
      "goFurther": "🛠️🛠️ A/B test two different value props for the same prospect type and track which gets more replies over 2 weeks."
    },
    {
      "number": 4,
      "title": "Build the follow-up sequence and CRM export",
      "time": "30 min",
      "description": "Generate a 3-touch follow-up sequence for no-reply prospects and push everything into your outreach tool.",
      "steps": [
        {
          "instruction": "Create `sequence.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the Sales Email Personalization Agent (part 1) - builds a\n3-touch follow-up sequence for prospects who don't reply to the first\nemail.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\nFOLLOWUP_DAYS = [3, 7, 14]\nMAX_WORDS = 60\n\n\ndef build_prompt(first_email, intel):\n    challenges = \", \".join(intel.get(\"challenges\", [])) or \"their business challenges\"\n\n    return f\"\"\"Original email sent:\n{first_email}\n\nProspect's challenges: {challenges}\n\nWrite a 3-email follow-up sequence for days 3, 7, and 14, each under\n{MAX_WORDS} words. Day 3 = gentle bump. Day 7 = new angle with a\ndifferent value prop or case study. Day 14 = a breakup email (this\noften gets the highest reply rate of the three, since it creates a\nsense of finality).\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"followups\": [{{\"day\": 3, \"text\": \"...\"}}, {{\"day\": 7, \"text\": \"...\"}}, {{\"day\": 14, \"text\": \"...\"}}]}}\"\"\"\n\n\ndef parse_sequence_reply(reply):\n    \"\"\"Defensive JSON parsing, same pattern used throughout this course. Returns None on real garbage.\"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        data = json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n    return data.get(\"followups\", [])\n\n\ndef validate_sequence(followups):\n    \"\"\"\n    Checks the sequence covers exactly days 3, 7, and 14 - a sequence\n    missing a touch (e.g. day 3 and 14 but no day 7) changes the whole\n    cadence's pacing and shouldn't be scheduled as-is.\n    \"\"\"\n    days_present = {f.get(\"day\") for f in followups}\n    missing = set(FOLLOWUP_DAYS) - days_present\n    return len(missing) == 0, missing\n\n\ndef build_followup_sequence(first_email, intel):\n    \"\"\"The main function. Give it the original email and intel, get back the validated 3-touch sequence.\"\"\"\n    prompt = build_prompt(first_email, intel)\n    reply = ask_ai(prompt, max_tokens=600, project=\"sales-email-personalization-agent\")\n\n    followups = parse_sequence_reply(reply)\n    if followups is None:\n        raise ValueError(\"The AI's reply wasn't valid JSON.\\nRun it again - this usually fixes itself.\")\n\n    is_complete, missing = validate_sequence(followups)\n    if not is_complete:\n        raise ValueError(f\"Sequence is missing day(s): {sorted(missing)}. Run it again.\")\n\n    return followups\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and the completeness\n    # guard work - no AI call, no credits spent:  python sequence.py\n    print(\"Checking a complete sequence passes validation...\")\n    complete = [{\"day\": 3, \"text\": \"a\"}, {\"day\": 7, \"text\": \"b\"}, {\"day\": 14, \"text\": \"c\"}]\n    is_complete, missing = validate_sequence(complete)\n    assert is_complete is True\n    print(\"  OK\")\n\n    print(\"\\nChecking a sequence missing day 7 is correctly caught...\")\n    incomplete = [{\"day\": 3, \"text\": \"a\"}, {\"day\": 14, \"text\": \"c\"}]\n    is_complete, missing = validate_sequence(incomplete)\n    assert is_complete is False\n    assert missing == {7}\n    print(\"  OK - missing day(s):\", missing)\n\n    print(\"\\nChecking parse_sequence_reply() strips a ```json code fence...\")\n    fenced = '```json\\n{\"followups\": [{\"day\": 3, \"text\": \"a\"}]}\\n```'\n    assert len(parse_sequence_reply(fenced)) == 1\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python sequence.py` (no AI call, no credits spent). You should see a complete 3-day sequence correctly pass validation, a sequence missing day 7 correctly caught, and a ```json-fenced reply correctly parsed - ending with `All checks passed.`"
        },
        {
          "instruction": "Create `crm_export.py` with this code (adapt the URL and payload shape to your actual sequencing tool - HubSpot Sequences and Outreach.io are noted in the comments):",
          "prompt": "\"\"\"\nStep 4 of the Sales Email Personalization Agent (part 2) - pushes the\nfull sequence into your outreach tool. Written as a clearly-marked\nadaptable template, since the exact API shape depends on whether you\nuse HubSpot Sequences, Outreach.io, or something else.\n\"\"\"\n\nimport requests\n\n\ndef build_steps_payload(prospect_email, steps):\n    \"\"\"\n    Turns the first email plus follow-ups into a list of\n    {\"send_day_offset\", \"recipient\", \"body\"} dicts - the shape most\n    sequencing tools expect, adapted to your specific tool's exact field\n    names before sending.\n\n        build_steps_payload(\"jordan@acme.com\", [{\"day\": 0, \"text\": \"...\"}, ...])\n\n    Pure function - tested below without a real CRM account.\n    \"\"\"\n    return [\n        {\"send_day_offset\": step[\"day\"], \"recipient\": prospect_email, \"body\": step[\"text\"]}\n        for step in steps\n    ]\n\n\ndef create_outreach_sequence(api_key, prospect_email, steps):\n    \"\"\"\n    ADAPT THIS to your actual sequencing tool before using it for real -\n    this shows the shape, not a working call to a specific product.\n\n    For HubSpot Sequences: POST to\n    https://api.hubapi.com/automation/v4/sequences/enrollments (check\n    HubSpot's current docs for the exact required fields).\n\n    For Outreach.io: POST to\n    https://api.outreach.io/api/v2/sequenceStates (check Outreach's\n    current docs for the exact required fields).\n    \"\"\"\n    payload = build_steps_payload(prospect_email, steps)\n\n    # Replace this URL and payload shape with your actual tool's API:\n    response = requests.post(\n        \"https://api.example-crm.com/v1/sequences\",\n        headers={\"Authorization\": f\"Bearer {api_key}\"},\n        json={\"steps\": payload},\n    )\n    response.raise_for_status()\n    return response.json()\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the payload-building works - no\n    # CRM account or network call needed:  python crm_export.py\n    steps = [{\"day\": 0, \"text\": \"First email body\"}, {\"day\": 3, \"text\": \"Follow-up 1\"}]\n    payload = build_steps_payload(\"jordan@acme.com\", steps)\n\n    assert payload[0] == {\"send_day_offset\": 0, \"recipient\": \"jordan@acme.com\", \"body\": \"First email body\"}\n    print(\"Built payload:\", payload)\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python crm_export.py`. You should see the payload correctly built in the shape most sequencing tools expect, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `main.py` with this code, then run the full pipeline end to end on one test prospect:",
          "prompt": "\"\"\"\nStep 4 of the Sales Email Personalization Agent (part 3) - chains every\nbuild together for one prospect.\n\nRun it with:  python main.py \"Jordan Lee\" \"Acme Robotics\" acme.com\n\"\"\"\n\nimport os\nimport sys\n\nfrom dotenv import load_dotenv\nfrom enrich import enrich_prospect\nfrom hunter import find_email\nfrom intelligence import extract_intelligence\nfrom mapping import map_value_props\nfrom sdt_ai import AIError\nfrom sequence import build_followup_sequence\nfrom subjects import generate_subject_lines\nfrom write_email import write_cold_email\n\nload_dotenv()\n\n\ndef run(name, company, domain, hunter_api_key):\n    print(f\"Researching {name} at {company}...\")\n    enriched = enrich_prospect(name, company)\n\n    first_name, *rest = name.split(\" \")\n    last_name = rest[-1] if rest else \"\"\n    email_result = find_email(first_name, last_name, domain, hunter_api_key)\n\n    if not email_result[\"usable\"]:\n        print(f\"  No usable email found (confidence: {email_result['confidence']}) - stopping here.\")\n        return\n\n    print(f\"  Found: {email_result['email']} (confidence {email_result['confidence']})\")\n\n    print(\"Extracting intelligence...\")\n    intel = extract_intelligence(name, company, enriched)\n\n    value_props = map_value_props(intel.get(\"challenges\", []))\n\n    print(\"Writing the cold email...\")\n    email_body = write_cold_email(name, company, intel, value_props[0])\n\n    print(\"Generating subject lines...\")\n    subjects = generate_subject_lines(email_body)\n\n    print(\"Building the follow-up sequence...\")\n    followups = build_followup_sequence(email_body, intel)\n\n    print(\"\\n=== EMAIL ===\")\n    print(email_body)\n    print(\"\\n=== TOP SUBJECT LINE ===\")\n    best_subject = min(subjects, key=lambda s: s.get(\"rank\", 99))\n    print(best_subject[\"text\"])\n    print(\"\\n=== FOLLOW-UP SEQUENCE ===\")\n    for followup in followups:\n        print(f\"Day {followup['day']}: {followup['text']}\")\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) < 4:\n        print('Usage: python main.py \"First Last\" \"Company Name\" companydomain.com')\n        sys.exit(1)\n\n    try:\n        run(sys.argv[1], sys.argv[2], sys.argv[3], os.environ[\"HUNTER_API_KEY\"])\n    except AIError as problem:\n        print(f\"AI request failed:\\n{problem}\")\n    except ValueError as problem:\n        print(f\"Could not complete the pipeline:\\n{problem}\")\n",
          "verify": "Run `python main.py \"First Last\" \"Company Name\" companydomain.com`. It should print the researched email, the personalized cold email, the top-ranked subject line, and the 3-touch follow-up sequence for days 3/7/14."
        }
      ],
      "goFurther": "🛠️🛠️ Add a \"reply detected\" webhook that pauses the follow-up sequence automatically if the prospect responds to the first email."
    }
  ],
  "portfolio": "Add this to your portfolio as \"AI Sales Prospecting & Personalization Agent\" -- a strong demo for SDR, BDR, or growth roles. Show a real (anonymized) example: the raw research, the extracted intelligence, and the final personalized email + sequence it produced -- plus the guards that kept it from sounding like generic AI copy.",
  "portfolioPrompt": "I just built an AI Sales Email Personalization Agent: given just a prospect's name and company, it researches their public presence and recent company news, finds a verified email via Hunter.io with a confidence threshold enforced in code, uses an AI gateway to extract their likely role and business challenges, maps those challenges to relevant value propositions, writes a personalized cold email checked against a list of generic filler phrases known to hurt reply rates, generates 5 ranked subject line options with a hard character limit, and builds a validated 3-touch follow-up sequence for non-responders.\n\nHelp me write:\n1. A 3-4 sentence portfolio project description focused on personalization at scale\n2. A LinkedIn post (under 150 words) for an SDR/BDR or sales leadership audience\n3. Two resume bullet points quantifying time saved per prospect and potential reply-rate improvement"
}$sess$::jsonb,
